{[x]
    / Compute tribonacci sequence: first x+1 values (tri(1) through tri(x+1))
    / We need to compute up to x+2 to handle forward references in odd indices
    n: x + 2;
    result: n # 0;
    / Base case: tri(1) = 3
    result[1]: 3;
    / Fill all even indices: tri(n) = 1 + n/2
    i: 2;
    while[i < n;
        result[i]: 1 + (i div 2);
        i: i + 2
    ];
    / Fill odd indices: tri(n) = tri(n-1) + tri(n-2) + tri(n+1)
    / Compute from index 3 upwards
    i: 3;
    while[i < n;
        if[i + 1 < n;
            result[i]: result[i - 1] + result[i - 2] + result[i + 1]
        ;
            / For the last odd index, compute the next even index first
            result[i + 1]: 1 + ((i + 1) div 2);
            result[i]: result[i - 1] + result[i - 2] + result[i + 1]
        ];
        i: i + 2
    ];
    / Return values from index 1 to x+1 (which is x+1 values)
    result[1 + til (x + 1)]
    }

