    value expr
    }

{[x]
    has_letters: any ({[c] (c <> lower c) | (c <> upper c)} each x);
    if[not has_letters;
        : reverse x
    ];
    {[c]
        $[(c = upper c) & (c <> lower c); lower c; (c = lower c) & (c <> upper c); upper c; c]
    } each x
    }

{[x]
    if[x ~ ""; : ""];
    system "echo -n '", x, "' | md5sum | awk '{print $1}'"
    }

{[x;y]
    range: til ((max(x; y) - min(x; y)) + 1);
    start: min(x; y);
    numbers: start + range;
    all_even_digits: {[n]
        digits: ("i"$ string n) - 48;
        all (digits mod 2) = 0
    } each numbers;
    numbers where all_even_digits
    }
